-- ============================================
-- LUMA — Thème 3 : MOYEN 3/3 x4 — Négocier le salaire
-- ============================================


update scenarios set content = '{"characters": {"recruiter": "le recruteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "We''d love to offer you the position, at a salary of $55,000 per year.", "text_fr": "On aimerait vous offrir le poste, à un salaire de 55 000$ par an.", "choices": [{"text": "Thank you so much! Is there any flexibility on that number?", "text_fr": "Merci beaucoup ! Y a-t-il une certaine flexibilité sur ce chiffre ?", "next": "n2"}, {"text": "I''m thrilled about the offer — based on my research, I was expecting closer to $62,000.", "text_fr": "Je suis ravi de l''offre — d''après mes recherches, je m''attendais à quelque chose de plus proche de 62 000$.", "next": "n2b"}]}, "n2": {"speaker": "recruiter", "text": "Let me ask — what number did you have in mind?", "text_fr": "Laissez-moi demander — vous aviez quel chiffre en tête ?", "choices": [{"text": "Based on market research, I was hoping for around $62,000.", "text_fr": "D''après mes recherches de marché, j''espérais autour de 62 000$.", "next": "n3"}, {"text": "Given my experience, something around $60,000 would feel fair.", "text_fr": "Vu mon expérience, quelque chose autour de 60 000$ me semblerait juste.", "next": "n3"}]}, "n2b": {"speaker": "recruiter", "text": "That''s a fair point. Let me see what we can do.", "text_fr": "C''est un point valable. Laissez-moi voir ce qu''on peut faire.", "choices": [{"text": "I appreciate you considering it.", "text_fr": "J''apprécie que vous y réfléchissiez.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "We might be able to go up to $58,000. Would that work for you?", "text_fr": "On pourrait peut-être aller jusqu''à 58 000$. Est-ce que ça vous conviendrait ?", "choices": [{"text": "That''s closer, thank you. Could we also discuss other benefits?", "text_fr": "C''est plus proche, merci. On pourrait aussi discuter d''autres avantages ?", "next": "n4"}, {"text": "I appreciate the movement — is there room to go a bit higher, closer to $60,000?", "text_fr": "J''apprécie l''effort — y a-t-il de la marge pour aller un peu plus haut, plus proche de 60 000$ ?", "next": "n4b"}]}, "n4": {"speaker": "recruiter", "text": "Sure, what other benefits are you interested in?", "text_fr": "Bien sûr, quels autres avantages vous intéressent ?", "choices": [{"text": "Extra vacation days would mean a lot to me.", "text_fr": "Des jours de congé supplémentaires compteraient beaucoup pour moi.", "next": "n5"}, {"text": "Remote work flexibility is important to me.", "text_fr": "La flexibilité du télétravail est importante pour moi.", "next": "n5"}]}, "n4b": {"speaker": "recruiter", "text": "Let me check with the team — I think we can meet in the middle at $59,000.", "text_fr": "Laissez-moi vérifier avec l''équipe — je pense qu''on peut se rencontrer à mi-chemin à 59 000$.", "choices": [{"text": "That works great for me, thank you for negotiating.", "text_fr": "Ça me convient parfaitement, merci d''avoir négocié.", "next": "n5"}]}, "n5": {"speaker": "recruiter", "text": "We can offer an extra week of vacation, and flexible remote days.", "text_fr": "On peut offrir une semaine de congé supplémentaire, et des jours de télétravail flexibles.", "choices": [{"text": "That sounds excellent, I''m happy with this package overall.", "text_fr": "Ça a l''air excellent, je suis satisfait de ce package dans l''ensemble.", "next": "n6"}]}, "n6": {"speaker": "recruiter", "text": "Great, I''ll get the formal offer letter prepared with these terms.", "text_fr": "Super, je vais préparer la lettre d''offre formelle avec ces conditions.", "choices": [{"text": "Thank you so much, I''m really excited to join the team.", "text_fr": "Merci beaucoup, je suis vraiment ravi de rejoindre l''équipe.", "next": "n7"}, {"text": "Perfect, when do you need my final decision by?", "text_fr": "Parfait, vous avez besoin de ma décision finale pour quand ?", "next": "n7b"}]}, "n7": {"speaker": "recruiter", "text": "We''re thrilled to have you. Welcome to the team!", "text_fr": "On est ravis de vous avoir. Bienvenue dans l''équipe !", "choices": [{"text": "Thank you, I can''t wait to get started.", "text_fr": "Merci, j''ai hâte de commencer.", "next": "end_negotiated"}]}, "n7b": {"speaker": "recruiter", "text": "Take a few days if you need — we''re confident you''ll say yes though!", "text_fr": "Prenez quelques jours si besoin — on est confiants que vous direz oui quand même !", "choices": [{"text": "Ha, I think I already know my answer — yes!", "text_fr": "Ha, je pense déjà connaître ma réponse — oui !", "next": "end_negotiated"}]}, "end_negotiated": {"speaker": "recruiter", "text": "Wonderful news! Welcome aboard, we''ll be in touch with the paperwork.", "text_fr": "Excellente nouvelle ! Bienvenue à bord, on vous recontacte pour les papiers.", "end": true, "ending_label": "Salaire négocié avec succès 💰✅"}}}'::jsonb, is_playable = true
where title = 'Négocier le salaire'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
